  const d=new Date(timestamp+330*60000),h=d.getUTCHours();
  const shift=h>=6&&h<14?'06-14':h>=14&&h<22?'14-22':'22-06';
  if(h<6)d.setUTCDate(d.getUTCDate()-1);
